const raw = String($input.item.json.output || '');

const marker = '---CONTENT---';
const markerIndex = raw.indexOf(marker);

let title = 'Untitled';
let content = raw;

if (markerIndex !== -1) {
  const before = raw.substring(0, markerIndex);
  content = raw.substring(markerIndex + marker.length).trim();

  const tIdx = before.indexOf('TITLE:');
  if (tIdx !== -1) {
    const afterTitle = before.substring(tIdx + 6);
    const newline = afterTitle.indexOf('\n');
    title = newline !== -1 ? afterTitle.substring(0, newline).trim() : afterTitle.trim();
  }
}

return [{ json: { title, content } }];
